import java.util.Arrays;

public class Solution {
    static class IntList {
        private int[] dados = new int[2];
        private int tamanho;

        void add(int value) { add(tamanho, value); }

        // O(n - index): desloca a cauda uma casa para a direita.
        void add(int index, int value) {
            if (index < 0 || index > tamanho) throw new IndexOutOfBoundsException(index);
            if (tamanho == dados.length) dados = Arrays.copyOf(dados, dados.length * 2);
            System.arraycopy(dados, index, dados, index + 1, tamanho - index);
            dados[index] = value;
            tamanho++;
        }

        // O(n - index): desloca a cauda uma casa para a esquerda.
        int remove(int index) {
            if (index < 0 || index >= tamanho) throw new IndexOutOfBoundsException(index);
            int removido = dados[index];
            System.arraycopy(dados, index + 1, dados, index, tamanho - index - 1);
            tamanho--;
            return removido;
        }

        int get(int index) {
            if (index < 0 || index >= tamanho) throw new IndexOutOfBoundsException(index);
            return dados[index];
        }

        int size() { return tamanho; }
    }
}

