import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    private static int[] conteudo(Solution.IntList l) {
        int[] r = new int[l.size()];
        for (int i = 0; i < r.length; i++) r[i] = l.get(i);
        return r;
    }

    @Test void insereNoMeioENoInicio() {
        var l = new Solution.IntList();
        l.add(10); l.add(30);
        l.add(1, 20);
        l.add(0, 5);
        assertArrayEquals(new int[]{5, 10, 20, 30}, conteudo(l));
    }

    @Test void removeDevolveEDesloca() {
        var l = new Solution.IntList();
        for (int i = 1; i <= 5; i++) l.add(i);
        assertEquals(3, l.remove(2));
        assertEquals(1, l.remove(0));
        assertArrayEquals(new int[]{2, 4, 5}, conteudo(l));
    }

    @Test void cresceAlemDaCapacidade() {
        var l = new Solution.IntList();
        for (int i = 0; i < 1000; i++) l.add(0, i);
        assertEquals(1000, l.size());
        assertEquals(999, l.get(0));
        assertEquals(0, l.get(999));
    }

    @Test void indicesInvalidos() {
        var l = new Solution.IntList();
        l.add(1);
        assertThrows(IndexOutOfBoundsException.class, () -> l.add(3, 9));
        assertThrows(IndexOutOfBoundsException.class, () -> l.remove(1));
        assertThrows(IndexOutOfBoundsException.class, () -> l.add(-1, 9));
    }
}
